20. Layer Controls
Use Leaflet’s built-in layers control to toggle base layers and overlays on/off:

id = "11120000"
base = dataRetrieval:::pkg.env$nldi_base

leaflet() |&gt;
  addProviderTiles(providers$CartoDB, group = "CartoDB") |&gt;
  addProviderTiles(providers$Esri.WorldTerrain, group = "Terrain") |&gt;
  addPolylines(data = read_sf(paste0(base, 'nwissite/USGS-', id, '/navigate/UT'))) |&gt;
  addPolygons(
    data = read_sf(paste0(base, 'nwissite/USGS-', id, '/basin')),
    fillColor = "transparent",
    color = "black",
    group = "Basin"
  ) |&gt;
  addLayersControl(
    baseGroups = c("CartoDB", "Terrain"),
    overlayGroups = c("Basin"),
    position = "topright"
  )

By defining groups, users can toggle layers between base maps and data overlays.

21. Function-ize: Reusable Map Code
Wrap mapping code in functions for reusability across multiple watersheds:

watershed_map &lt;- function(gage_id) {
  base &lt;- dataRetrieval:::pkg.env$nldi_base

  leaflet() |&gt;
    addProviderTiles(providers$CartoDB) |&gt;
    addPolylines(
      data = read_sf(paste0(base, 'nwissite/USGS-', gage_id, '/navigate/UT'))
    ) |&gt;
    addPolygons(
      data = read_sf(paste0(base, 'nwissite/USGS-', gage_id, '/basin')),
      fillColor = "transparent",
      color = "black",
      group = "Basin"
    ) |&gt;
    addWMSTiles(
      "http://mesonet.agron.iastate.edu/cgi-bin/wms/nexrad/n0r.cgi",
      layers = "nexrad-n0r-900913",
      options = WMSTileOptions(format = "image/png", transparent = TRUE)
    )
}

watershed_map("06752260")

Now one function generates maps for any USGS gauge ID.

22. Adding Map Details: Measure, Graticule, Mini Map
Enhance maps with interactive measurement tools:

watershed_map("06752260") |&gt;
  addMeasure() |&gt;
  addGraticule() |&gt;
  addMiniMap()

Tools added: - addMeasure() — click to measure distances - addGraticule() — lat/lon reference grid - addMiniMap() — small inset map for zoomed-in views

23. leafem: Home Buttons & Mouse Coordinates
The leafem package extends leaflet with navigation utilities:

library(leafem)

watershed_map("06752260") |&gt;
  addMeasure() |&gt;
  addGraticule() |&gt;
  leafem::addHomeButton(group = "Basin") |&gt;
  leafem::addMouseCoordinates()

Features: - addHomeButton() — zoom back to initial extent - addMouseCoordinates() — display lat/lon on cursor movement - Extends leaflet without breaking existing code

24. leafpop: Interactive Popup Tables
Display data tables in popups using leafpop:

library(leafpop)

starbucks &lt;- read_csv('data/directory.csv') |&gt;
  filter(City %in% c("Fort Collins", "Loveland"), State == "CO") |&gt;
  st_as_sf(coords = c("Longitude", "Latitude"), crs = 4326)

leaflet(data = starbucks) |&gt;
  addProviderTiles(providers$CartoDB) |&gt;
  addCircleMarkers(
    color = "brown",
    fillOpacity = 0.7,
    stroke = FALSE,
    popup = leafpop::popupTable(
      st_drop_geometry(starbucks[, 1:5]),
      feature.id = FALSE,
      row.numbers = FALSE
    )
  )

Why: Rich, interactive tables in popups make data more accessible to map users.

