Step 3.2 — Point-in-polygon function

point_in_polygon &lt;- function(points_sf, polygons_sf, id_col) {
  # Spatial join: assign each point to containing polygon
  joined &lt;- st_join(polygons_sf, points_sf, join = st_contains)

  # Count points per polygon
  result &lt;- joined %&gt;%
    group_by(.data[[id_col]]) %&gt;%
    summarise(n = n(), .groups = "drop")

  return(result)
}

